import Redis from 'ioredis';

// IMPORTANT: Use separate connections for pub and sub
// A subscribed connection can ONLY use subscribe commands
const subscriber = new Redis();
const publisher = new Redis();

// Subscribe to a channel
await subscriber.subscribe('chat:room1');

// Listen for messages
subscriber.on('message', (channel, message) => {
  console.log(`[${channel}] ${message}`);
});

// Pattern subscribe
await subscriber.psubscribe('orders.*');
subscriber.on('pmessage', (pattern, channel, message) => {
  console.log(`Pattern: ${pattern}, Channel: ${channel}, Message: ${message}`);
});

// Publish from another connection
await publisher.publish('chat:room1', JSON.stringify({ user: 'Alice', text: 'Hello!' }));
await publisher.publish('orders.created', JSON.stringify({ orderId: 42, total: 99.99 }));

// Cleanup
await subscriber.unsubscribe('chat:room1');
await subscriber.punsubscribe('orders.*');

# Enable expired key notifications
redis-cli CONFIG SET notify-keyspace-events "Ex"

# Subscribe to expired key events on database 0
redis-cli
SUBSCRIBE __keyevent@0__:expired

# When any key expires, you get a notification:
# 1) "message"
# 2) "__keyevent@0__:expired"
# 3) "session:abc123"   <- the expired key name

# Node.js: react when a session expires
await subscriber.subscribe('__keyevent@0__:expired');
subscriber.on('message', (channel, key) => {
  if (key.startsWith('session:')) {
    console.log('Session expired:', key);
    cleanupUserSession(key);
  }
});
